import 'package:flutter_test/flutter_test.dart';
import 'package:treasurenet_mobile/core/utils/clue_crypto.dart';
import 'package:treasurenet_mobile/core/utils/hex_utils.dart';

/// Fixed vector generated by the GM console scheme (WebCrypto HKDF +
/// AES-GCM wrap) so Flutter decryption stays byte-exact with the browser.
const _manifestId =
    'sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';
const _clueKeyHex =
    '0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20';
const _ivB64 = 'yMnKy8zNzs/Q0dLT';
const _ciphertextB64 =
    'zLXz/8Ti7Pu7TV9kH8gSRpw2CCplayBSrff83BBI3DQOpTFFHAt5w0KtROy4T6xcFga9btWb1/yst7cz9nU=';
const _keyWrappedB64 =
    'zvcrHhb47NUaK36KQhhsFdJuQrjTFhK+cu71ZrvL7LUapymhifpyaMW7S33Si/m7';
const _plaintext = 'The beacon stands where the ferry queue forms.';

void main() {
  test('unwrapClueKey recovers the browser-generated AES key', () async {
    final key = await unwrapClueKey(
      manifestId: _manifestId,
      keyWrappedB64: _keyWrappedB64,
    );
    expect(bytesToHex(key), _clueKeyHex);
  });

  test('decryptClue reproduces the GM console plaintext', () async {
    final plaintext = await decryptClue(
      manifestId: _manifestId,
      keyWrappedB64: _keyWrappedB64,
      ivB64: _ivB64,
      ciphertextB64: _ciphertextB64,
    );
    expect(plaintext, _plaintext);
  });

  test('tampered wrapped key fails authentication', () async {
    final tampered =
        _keyWrappedB64.replaceRange(0, 4, 'AAAA');
    expect(
      () => unwrapClueKey(manifestId: _manifestId, keyWrappedB64: tampered),
      throwsA(anything),
    );
  });
}
